// Format a plain alert message from the error payload n8n passes in.
const data = $input.first().json;
const workflowName = (data.workflow && data.workflow.name) || 'unknown workflow';
const lastNode = (data.execution && data.execution.lastNodeExecuted) || 'unknown node';
const message = (data.execution && data.execution.error && data.execution.error.message) || 'no error message';
const url = (data.execution && data.execution.url) || 'no execution url';

const text = [
  'Workflow failed: ' + workflowName,
  'Failing node: ' + lastNode,
  'Error: ' + message,
  'Execution: ' + url
].join('\n');

return [{ json: { text } }];
